@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800&family=Tajawal:wght@400;500;700&display=swap');
@import "tailwindcss";

@theme {
  --font-sans: "Cairo", "Tajawal", system-ui, sans-serif;

  /* Primary color matching the screenshot (vibrant soft indigo) */
  --color-primary-50: #f0efff;
  --color-primary-100: #e0dffd;
  --color-primary-500: #7b78ff;
  --color-primary-600: #5c59e8;
  --color-primary-700: #4a47b9;

  /* Alias indigo to primary so existing classes update instantly */
  --color-indigo-50: var(--color-primary-50);
  --color-indigo-100: var(--color-primary-100);
  --color-indigo-500: var(--color-primary-500);
  --color-indigo-600: var(--color-primary-600);
  --color-indigo-700: var(--color-primary-700);

  /* Clean slate grays for text and borders */
  --color-slate-50: #f8f9fa;
  --color-slate-100: #f1f3f5;
  --color-slate-200: #e9ecef;
  --color-slate-300: #dee2e6;
  --color-slate-800: #343a40;
  --color-slate-900: #212529;

  /* Custom extremely soft shadows like the image */
  --shadow-sm: 0 4px 20px rgba(0, 0, 0, 0.03);
  --shadow-md: 0 10px 30px rgba(0, 0, 0, 0.04);
}

html, body, #root {
  height: 100%;
}

body {
  font-family: var(--font-sans);
  background: #f4f7fa; /* Very clean, cool light gray matching screenshot */
  color: var(--color-slate-800);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Base borders */
*, ::before, ::after { 
  border-color: var(--color-slate-200); 
}

button, a, input, select, textarea { -webkit-tap-highlight-color: transparent; }
input, select, textarea { font: inherit; }
